{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { evaluateAll, colName } from './eval.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map() // key -> {col,row,content}
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const content = s.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) fail(`line ${i + 1}: invalid cell address ${addr}`)
  const col = colIndex(am[1].toUpperCase())
  const row = Number(am[2])
  const key = col * 1000 + row
  if (cells.has(key)) fail(`line ${i + 1}: cell ${am[1].toUpperCase()}${row} is declared twice`)
  cells.set(key, { col, row, content })
}

function colIndex(l) {
  return l.length === 1 ? l.charCodeAt(0) - 64 : 26 + (l.charCodeAt(0) - 65) * 26 + (l.charCodeAt(1) - 64)
}
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const keys = [...cells.keys()].sort((a, b) => a - b)
let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const k of keys) {
    const c = cells.get(k)
    out += `${colName(c.col)}${c.row}=${vals.get(k)}\n`
  }
} else {
  for (const k of keys) {
    const c = cells.get(k)
    let line = `${colName(c.col)}${c.row}:`
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p) {
        const set = new Set()
        collect(p.ast, set)
        for (const d of [...set].sort((a, b) => a - b)) line += ` ${colName(Math.floor(d / 1000))}${d % 1000}`
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)

function collect(n, set) {
  if (n.t === 'ref') {
    if (n.addr) set.add(n.addr.col * 1000 + n.addr.row)
  } else if (n.t === 'range') {
    if (n.a && n.b) {
      for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
        for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) set.add(c * 1000 + r)
    }
  } else if (n.t === 'bin') {
    collect(n.l, set)
    collect(n.r, set)
  } else if (n.t === 'un') collect(n.e, set)
  else if (n.t === 'call') for (const a of n.args) collect(a, set)
}
"}

