{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { evaluateAll, colName } from './eval.js'

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'values' && mode !== 'deps')) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()

const cells = new Map() // key -> {col,row,content}
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)
  const addr = m[0]
  const content = s.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  if (!am || Number(am[2]) < 1) fail(`line ${i + 1}: invalid cell address ${addr}`)
  const col = colIndex(am[1].toUpperCase())
  const row = Number(am[2])
  const key = col * 1000 + row
  if (cells.has(key)) fail(`line ${i + 1}: cell ${am[1].toUpperCase()}${row} is declared twice`)
  cells.set(key, { col, row, content })
}

function colIndex(l) {
  return l.length === 1 ? l.charCodeAt(0) - 64 : 26 + (l.charCodeAt(0) - 65) * 26 + (l.charCodeAt(1) - 64)
}
function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

const keys = [...cells.keys()].sort((a, b) => a - b)
let out = ''
if (mode === 'values') {
  const vals = evaluateAll(cells)
  for (const k of keys) {
    const c = cells.get(k)
    out += `${colName(c.col)}${c.row}=${vals.get(k)}\n`
  }
} else {
  for (const k of keys) {
    const c = cells.get(k)
    let line = `${colName(c.col)}${c.row}:`
    if (c.content[0] === '=') {
      const p = parseFormula(c.content.slice(1))
      if (p) {
        const set = new Set()
        collect(p.ast, set)
        for (const d of [...set].sort((a, b) => a - b)) line += ` ${colName(Math.floor(d / 1000))}${d % 1000}`
      }
    }
    out += line + '\n'
  }
}
process.stdout.write(out)

function collect(n, set) {
  if (n.t === 'ref') {
    if (n.addr) set.add(n.addr.col * 1000 + n.addr.row)
  } else if (n.t === 'range') {
    if (n.a && n.b) {
      for (let c = Math.min(n.a.col, n.b.col); c <= Math.max(n.a.col, n.b.col); c++)
        for (let r = Math.min(n.a.row, n.b.row); r <= Math.max(n.a.row, n.b.row); r++) set.add(c * 1000 + r)
    }
  } else if (n.t === 'bin') {
    collect(n.l, set)
    collect(n.r, set)
  } else if (n.t === 'un') collect(n.e, set)
  else if (n.t === 'call') for (const a of n.args) collect(a, set)
}
"}

{"file_path":"src/parse.js","content":"export function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const l = m[1].toUpperCase()
  const col = l.length === 1 ? l.charCodeAt(0) - 64 : 26 + (l.charCodeAt(0) - 65) * 26 + (l.charCodeAt(1) - 64)
  return { col, row }
}

function lex(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const ch = s[i]
    if (ch === ' ' || ch === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) })
      i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] })
      i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] })
      i += m[0].length
    } else return null
  }
  return toks
}

// Returns { ast, badRange } or null when the grammar rejects the body.
export function parseFormula(src) {
  const toks = lex(src)
  if (!toks) return null
  let p = 0
  let badRange = false
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const FAIL = {}

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) {
      p++
      return { t: 'bin', op: '^', l, r: pow() }
    }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary(argPos) {
    const tk = toks[p]
    if (!tk) throw FAIL
    if (tk.k === 'num') { p++; return { t: 'num', v: tk.v } }
    if (tk.k === 'op' && tk.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw FAIL
      p++
      return e
    }
    if (tk.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) throw FAIL
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw FAIL
        }
        return { t: 'call', name: tk.v.toUpperCase(), args }
      }
      const up = tk.v.toUpperCase()
      if (isOp(':')) {
        p++
        const t2 = toks[p]
        if (!t2 || t2.k !== 'word') throw FAIL
        p++
        return { t: 'range', a: parseAddr(tk.v), b: parseAddr(t2.v) }
      }
      if (up === 'TRUE') return { t: 'bool', v: true }
      if (up === 'FALSE') return { t: 'bool', v: false }
      return { t: 'ref', addr: parseAddr(tk.v) }
    }
    throw FAIL
  }
  function arg() {
    const e = cmp()
    return e
  }
  function check(n, direct) {
    if (n.t === 'range') { if (!direct) badRange = true }
    else if (n.t === 'bin') { check(n.l, false); check(n.r, false) }
    else if (n.t === 'un') check(n.e, false)
    else if (n.t === 'call') for (const a of n.args) check(a, true)
  }
  try {
    const ast = cmp()
    if (p < toks.length) return null
    check(ast, false)
    return { ast, badRange }
  } catch (e) {
    if (e === FAIL) return null
    throw e
  }
}
"}

